module radix2_div(
    input clk, 
    input rst, 
    input sign, 
    input [7:0] dividend, 
    input [7:0] divisor, 
    input opn_valid, 
    output reg res_valid, 
    output reg [15:0] result
);
// Internal signals
reg [7:0] abs_dividend;
reg [7:0] neg_divisor;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
// Combinational logic
wire [7:0] sub_result;
wire [7:0] mux_result;
// Behavioral modeling
always @(posedge clk or posedge rst) begin
    if (rst) begin
        abs_dividend <= 0;
        neg_divisor <= 0;
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
    end else begin
        if (opn_valid && !res_valid) begin
            abs_dividend <= (sign && dividend[7]) ? (~dividend + 1) : dividend;
            neg_divisor <= (sign && divisor[7]) ? (~divisor + 1) : divisor;
            SR <= {abs_dividend << 1};
            cnt <= 1;
            start_cnt <= 1;
        end
    end
end
// Combinational logic for division operation
always @(*) begin
    if (start_cnt) begin
        if (cnt[3]) begin
            cnt = 0;
            start_cnt = 0;
            SR = {sub_result, SR[7:1]};
        end else begin
            cnt = cnt + 1;
            SR = {mux_result, SR[7:1]};
        end
    end
end
// Subtraction operation
assign sub_result = SR[15:8] - neg_divisor;
// Multiplexer selection based on carry_out
assign mux_result = sub_result[7] ? SR[15:8] : sub_result;
// Output assignment
always @(posedge clk or posedge rst) begin
    if (rst) begin
        res_valid <= 0;
    end else begin
        res_valid <= cnt[3] || (res_valid && res_valid);
    end
end
always @(*) begin
    if (res_valid) begin
        result = {SR[15:8], SR[7:0]};
    end
end
endmodule
